//
//  QuizAnswers.swift
//  Replog
//
//  The onboarding intake. Feeds the deterministic PlanGenerator.
//

import Foundation

enum Experience: String, Codable, CaseIterable, Identifiable, Sendable {
    case beginner, intermediate, advanced
    var id: String { rawValue }
    var displayName: String { rawValue.capitalized }
}

enum Gender: String, Codable, CaseIterable, Identifiable, Sendable {
    case male, female, preferNotToSay
    var id: String { rawValue }
    var displayName: String {
        switch self {
        case .male: return "Male"
        case .female: return "Female"
        case .preferNotToSay: return "Prefer not to say"
        }
    }
}

enum Sport: String, Codable, CaseIterable, Identifiable, Sendable {
    case running, swimming, football, basketball, cycling, boxing, volleyball, other
    var id: String { rawValue }
    var displayName: String {
        switch self {
        case .other: return "Other"
        default: return rawValue.capitalized
        }
    }

    /// Muscles a sport most depends on, highest priority first. `.other` has no fixed
    /// mapping — the plan falls back to general priorities.
    var priorityMuscles: [Muscle] {
        switch self {
        case .running:    return [.quadriceps, .hamstrings, .calves, .glutes, .abdominals]
        case .swimming:   return [.lats, .shoulders, .chest, .triceps, .middleBack]
        case .football:   return [.quadriceps, .hamstrings, .glutes, .calves, .abdominals]
        case .basketball: return [.quadriceps, .calves, .glutes, .shoulders, .abdominals]
        case .cycling:    return [.quadriceps, .hamstrings, .glutes, .calves, .abdominals]
        case .boxing:     return [.shoulders, .lats, .abdominals, .triceps, .calves]
        case .volleyball: return [.quadriceps, .calves, .shoulders, .glutes, .abdominals]
        case .other:      return []
        }
    }
}

enum Injury: String, Codable, CaseIterable, Identifiable, Sendable {
    case knee, shoulder, lowerBack, postInjuryRecovery
    var id: String { rawValue }
    var displayName: String {
        switch self {
        case .knee: return "Knee"
        case .shoulder: return "Shoulder"
        case .lowerBack: return "Lower back"
        case .postInjuryRecovery: return "Post-injury recovery"
        }
    }
    /// Muscle regions to avoid loading for this limitation.
    var avoidMuscles: [Muscle] {
        switch self {
        case .knee: return [.quadriceps, .hamstrings, .calves]
        case .shoulder: return [.shoulders]
        case .lowerBack: return [.lowerBack]
        case .postInjuryRecovery: return []
        }
    }
}

extension Equipment {
    /// The primary training equipment types offered as onboarding choices (bodyweight last).
    static let selectable: [Equipment] = [
        .barbell, .dumbbell, .machine, .cable, .kettlebells, .bands, .ezCurlBar, .bodyOnly
    ]
}

enum EquipmentAccess: String, Codable, CaseIterable, Identifiable, Sendable {
    case fullGym, home, bodyweight
    var id: String { rawValue }
    var displayName: String {
        switch self {
        case .fullGym: return "Full gym"
        case .home: return "Home (dumbbells)"
        case .bodyweight: return "Bodyweight only"
        }
    }
    /// The equipment types this access level permits.
    var allowedEquipment: Set<Equipment> {
        switch self {
        case .fullGym:
            return [.barbell, .dumbbell, .machine, .cable, .bodyOnly, .bands,
                    .kettlebells, .ezCurlBar, .exerciseBall, .foamRoll, .medicineBall, .other]
        case .home:
            return [.dumbbell, .bodyOnly, .bands, .kettlebells, .exerciseBall, .foamRoll, .medicineBall]
        case .bodyweight:
            return [.bodyOnly, .bands]
        }
    }
}

struct QuizAnswers: Equatable, Sendable {
    var firstName: String = ""
    var goal: Goal = .buildMuscle
    var sport: Sport? = nil
    /// Free-text sport name, used only when `sport == .other`.
    var customSport: String = ""
    var experience: Experience = .beginner
    var gender: Gender = .male
    var age: Int = 28
    /// Body height in centimetres (stored metric; display converts at the edge).
    var heightCm: Int = 175
    /// Body weight in kilograms (stored metric).
    var bodyWeightKg: Double = 75
    var daysPerWeek: Int = 3
    var minutesPerSession: Int = 45
    var injuries: Set<Injury> = []
    var equipment: EquipmentAccess = .fullGym
    /// Specific equipment types the user trains with. Empty means "use whatever my access
    /// level allows"; non-empty restricts the plan to exactly these types.
    var equipmentTypes: Set<Equipment> = []

    /// The equipment the plan may use — the chosen types, or the access level's default set.
    var allowedEquipment: Set<Equipment> {
        equipmentTypes.isEmpty ? equipment.allowedEquipment : equipmentTypes
    }

    /// Human-readable list of the equipment the plan may use (for the AI prompt & report).
    var equipmentDescription: String {
        let names = Equipment.selectable.filter { allowedEquipment.contains($0) }.map(\.displayName)
        return names.isEmpty ? equipment.displayName : names.joined(separator: ", ")
    }

    /// All muscle regions to avoid, derived from selected injuries.
    var avoidedMuscles: Set<Muscle> {
        Set(injuries.flatMap(\.avoidMuscles))
    }

    /// Trimmed first name, or empty if none given. (We only collect a first name.)
    var fullName: String {
        firstName.trimmingCharacters(in: .whitespaces)
    }

    /// Human-facing sport label: the free-text value when "Other", else the enum name.
    /// Empty when no sport applies.
    var sportLabel: String {
        guard let sport else { return "" }
        return sport == .other ? customSport.trimmingCharacters(in: .whitespaces) : sport.displayName
    }

    /// Body-mass index from height & weight, or nil if height is unset.
    var bmi: Double? {
        guard heightCm > 0 else { return nil }
        let m = Double(heightCm) / 100
        return bodyWeightKg / (m * m)
    }

    /// A plain-language BMI band used in the coach report.
    var bmiCategory: String? {
        guard let bmi else { return nil }
        switch bmi {
        case ..<18.5: return "underweight"
        case 18.5..<25: return "a healthy weight"
        case 25..<30: return "overweight"
        default: return "in the obese range"
        }
    }
}

//
//  CoachingKnowledge.swift
//  Replog
//
//  A curated, evidence-based "coaching cheat-sheet" injected into the model's system prompt
//  so its programming decisions are grounded in established exercise science — not generic
//  guesses. This is the practical, on-device way to "feed science" into Apple Intelligence:
//  the model has a small context window, so we distill principles here rather than dumping
//  raw papers. Edit/extend this text to refine the model's scientific behavior.
//
//  (If you later want true paper-grounding, this is where a retrieval step would inject the
//  most relevant snippets per request — see notes in the PR/README.)
//

import Foundation

enum CoachingKnowledge {

    /// Distilled, evidence-based resistance-training principles. Kept compact to fit the
    /// on-device model's context window.
    static let principles = """
    EVIDENCE-BASED TRAINING PRINCIPLES (apply these):
    • Volume: ~10-20 hard sets per muscle per week drives hypertrophy; beginners progress on the \
    lower end, advanced trainees nearer the top. More is not always better.
    • Frequency: training each muscle ~2x/week beats 1x for the same weekly volume (protein \
    synthesis stays elevated ~48h).
    • Intensity & reps: 6-12 reps is the hypertrophy core, but 5-30 reps near failure all build \
    muscle; 3-6 reps bias strength; 12-20 bias muscular endurance / metabolic stress.
    • Proximity to failure: most working sets at RPE 7-9 (1-3 reps in reserve). True failure \
    sparingly, mostly on isolation/machine work.
    • Progressive overload: add load, reps, or sets over time. Small, consistent increments win.
    • Exercise order: compound, multi-joint lifts first when fresh; isolation and machines later.
    • Split logic: pair synergists (e.g. chest/shoulders/triceps = push) or use upper/lower or \
    full-body by available days; balance push/pull and knee/hip patterns to avoid imbalance.
    • Selection: cover each target muscle's main function; mix a heavy compound with 1-2 \
    isolation/stretch-position movements; respect equipment available.
    • Recovery: ~48h before training a muscle hard again; sleep and protein (~1.6-2.2 g/kg/day) \
    underpin adaptation.
    • Injuries: never load a flagged joint/region as a primary mover; choose pain-free, \
    joint-friendly variations and brace/warm up thoroughly.
    """

    /// Prepends the principles to a role/system instruction.
    static func grounded(_ instruction: String) -> String {
        instruction + "\n\n" + principles
    }
}

//
//  ProgressAggregator.swift
//  Replog
//
//  Turns an exercise's history into the numbers the Progress screens show:
//  best & current estimated 1RM, trend %, and a sparkline series.
//

import Foundation

struct ExerciseProgress: Equatable, Sendable {
    var exId: String
    var bestE1rm: Int
    var currentE1rm: Int
    /// Percent change of the latest session's e1RM vs the prior session, or nil.
    var trendPercent: Double?
    /// e1RM over time (oldest -> newest) for the chart/sparkline.
    var series: [Int]
    var sessionCount: Int

    var hasData: Bool { sessionCount > 0 }
    var trend: Trend {
        guard let trendPercent else { return .none }
        if trendPercent > 0 { return .up }
        if trendPercent < 0 { return .down }
        return .flat
    }
}

enum ProgressAggregator {
    /// Summarizes a single exercise's history (any order; sorted internally by date).
    static func summarize(exId: String, history: [HistoryEntry]) -> ExerciseProgress {
        let sorted = history.sorted { $0.date < $1.date }
        let series = sorted.map(\.e1rm)
        let best = series.max() ?? 0
        let current = series.last ?? 0
        let previous = series.count >= 2 ? series[series.count - 2] : nil
        let trend = TrendCalculator.percentChange(current: Double(current),
                                                  previous: previous.map(Double.init))
        return ExerciseProgress(
            exId: exId,
            bestE1rm: best,
            currentE1rm: current,
            trendPercent: trend,
            series: series,
            sessionCount: sorted.count
        )
    }
}

